DROP TABLE IF EXISTS `poll_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `poll_log` (
  `ts` datetime NOT NULL,
  `ap_id` varchar(32) NOT NULL,
