--
-- Table structure for table `sessions`
--

DROP TABLE IF EXISTS `sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sessions` (
  `session_id` varchar(16) NOT NULL,
  `room_id` varchar(32) NOT NULL,
  `start_time` datetime NOT NULL,
  `end_time` datetime NOT NULL,
  `scenario_people` int NOT NULL,
  `activity` varchar(16) NOT NULL,
  `participant_group` varchar(32) NOT NULL,
  `is_holdout` tinyint(1) NOT NULL,
  PRIMARY KEY (`session_id`),
  CONSTRAINT `chk_sessions_activity` CHECK ((`activity` in (_utf8mb4'empty',_utf8mb4'rendah',_utf8mb4'sedang',_utf8mb4'tinggi',_utf8mb4'crowded'))),
  CONSTRAINT `sessions_chk_1` CHECK ((`scenario_people` >= 0)),
  CONSTRAINT `sessions_chk_3` CHECK ((`end_time` > `start_time`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

